    # This is a very simple parser for a subset of CSS
    # Returns a list of (tag, id, classes, nth_child)

    # Split by comma for multiple selectors
    parts = [s.strip() for s in selector.split(',')]
    result = []
    for part in parts:
        # Split by space for descendant selectors
        subparts = part.split()
        subresult = []
        for subpart in subparts:
            # Match tag, id, class, nth-child
            tag = re.search(r'^[a-zA-Z0-9*]+', subpart)
            tag = tag.group(0) if tag else None

            id_match = re.search(r'#([a-zA-Z0-9_-]+)', subpart)
            id_val = id_match.group(1) if id_match else None

            classes = re.findall(r'\.([a-zA-Z0-9_-]+)', subpart)

            nth_match = re.search(r':nth-child\((\d+)\)', subpart)
            nth = int(nth_match.group(1)) if nth_match else None

            subresult.append({'tag': tag, 'id': id_val, 'classes': classes, 'nth': nth})
        result.append(subresult)
    return result

