                lines = child.strip().splitlines()
                for line in lines:
                    if line.strip():
                        res += "  " * (indent + 1) + line.strip() + "\n"
            else:
                res += child

    if pretty and not only_text and node.children:
        res += "  " * indent

    res += f"</{node.tag}>"
    if pretty:
        res += "\n"
    return res

