        if self.stack:
            self.stack[-1].children.append(data)

    def handle_startendtag(self, tag, attrs):
        node = Node(tag, attrs, self.stack[-1])
        node.is_self_closing = True
        self.stack[-1].children.append(node)

def parse_selector(selector_str):
    if not selector_str:
        return [[{'tag': 'html', 'id': None, 'classes': [], 'nth': None}]]

    comma_parts = [s.strip() for s in selector_str.split(',')]
    all_selectors = []
    for part in comma_parts:
        space_parts = part.split()
        subselectors = []
        for sub in space_parts:
            tag_match = re.match(r'^([a-zA-Z0-9*]+)', sub)
            tag = tag_match.group(1) if tag_match else None

            id_val = None
            id_match = re.search(r'#([a-zA-Z0-9_-]+)', sub)
            if id_match: id_val = id_match.group(1)

            classes = re.findall(r'\.([a-zA-Z0-9_-]+)', sub)

            nth = None
            nth_match = re.search(r':nth-child\((\d+)\)', sub)
            if nth_match: nth = int(nth_match.group(1))

            subselectors.append({'tag': tag, 'id': id_val, 'classes': classes, 'nth': nth})
        all_selectors.append(subselectors)
    return all_selectors

def match_node(node, sel):
    if not isinstance(node, Node): return False
    if sel['tag'] and sel['tag'] != '*' and node.tag != sel['tag']: return False
    if sel['id'] and node.attrs.get('id') != sel['id']: return False
    for cls in sel['classes']:
        if cls not in node.attrs.get('class', '').split(): return False
    if sel['nth'] is not None:
        if not node.parent: return False
        count = 0
        for child in node.parent.children:
            if isinstance(child, Node):
                count += 1
                if child == node:
                    return count == sel['nth']
        return False
    return True

def search_tree(node, sel):
    results = []
    if match_node(node, sel):
        results.append(node)
    for child in node.children:
        if isinstance(child, Node):
            results.extend(search_tree(child, sel))
    return results

def apply_selector(root, selector_list):
    current_nodes = [root]
    for sel in selector_list:
        next_nodes = []
        for node in current_nodes:
            # We want to search for descendants matching 'sel'
            # But not include the node itself unless it's the root?
            # Actually, the standard is to look in descendants.
            for child in node.children:
                if isinstance(child, Node):
                    next_nodes.extend(search_tree(child, sel))
        current_nodes = next_nodes
    return current_nodes

def serialize(node, pretty=False, indent=0):
    if not isinstance(node, Node):
        return node

    attr_str = "".join(f' {k}="{v}"' for k, v in sorted(node.attrs.items()))
    res = ("  " * indent if pretty else "") + f"<{node.tag}{attr_str}>"

    if node.is_self_closing:
        return res + ("\n" if pretty else "")

    # Matching the weird htmlq pretty print is hard.
    # Let's try a simple version.
    child_res = ""
    for child in node.children:
        child_res += serialize(child, pretty, indent + 1)

    if pretty and any(isinstance(c, Node) for c in node.children):
        res += "\n" + child_res + ("  " * indent)
    else:
        res += child_res

    res += f"</{node.tag}>"
    if pretty: res += "\n"
    return res

def remove_from_tree(node, sel_list):
    new_children = []
    for child in node.children:
        if isinstance(child, Node):
            to_remove = False
            for sel_path in sel_list:
                # Simplified: only check if the node itself matches the LAST part of the removal selector
                if match_node(child, sel_path[-1]):
                    to_remove = True
                    break
            if not to_remove:
                remove_from_tree(child, sel_list)
                new_children.append(child)
        else:
            new_children.append(child)
    node.children = new_children

def main():
    parser = argparse.ArgumentParser(add_help=False)
    parser.add_argument('-h', '--help', action='store_true')
    parser.add_argument('-V', '--version', action='store_true')
    parser.add_argument('-t', '--text', action='store_true')
    parser.add_argument('-p', '--pretty', action='store_true')
    parser.add_argument('-w', '--ignore-whitespace', action='store_true')
    parser.add_argument('-a', '--attribute')
    parser.add_argument('-b', '--base')
    parser.add_argument('-B', '--detect-base', action='store_true')
    parser.add_argument('-f', '--filename')
    parser.add_argument('-o', '--output')
